\u0420\u0430\u0437\u0434\u0435\u043b \u00ab\u043e\u0436\u0438\u0434\u0430\u0435\u043c\u044b\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b\u00bb \u043e\u043f\u0438\u0441\u044b\u0432\u0430\u0435\u0442 \u043f\u0440\u043e\u0433\u043d\u043e\u0437\u044b \u0438 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0438 \u043f\u0440\u0438\u0451\u043c\u043a\u0438, \u0430 \u043d\u0435 \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043f\u0440\u043e\u0433\u043e\u043d\u044b.\n\n## 1. \u0426\u0435\u043b\u044c \u0438 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u043c\u044b\u0435 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0438 \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u043e\u0441\u0442\u0438\n\n**\u0426\u0435\u043b\u044c \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0430:** \u0441\u043f\u0440\u043e\u0435\u043a\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0443, \u0447\u0442\u043e \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u0430 \u0441\u043e\u0440\u0442\u0438\u0440\u0443\u0435\u0442 \u0432\u0445\u043e\u0434\u043d\u043e\u0439 \u0441\u043f\u0438\u0441\u043e\u043a \u0441\u043b\u043e\u0432 \u043f\u043e \u0430\u043b\u0444\u0430\u0432\u0438\u0442\u0443 (\u0432 \u0432\u044b\u0431\u0440\u0430\u043d\u043d\u043e\u043c \u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u043c \u043f\u043e\u0440\u044f\u0434\u043a\u0435 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f) \u0438 \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u0440\u043e\u0432\u043d\u043e \u043e\u0434\u043d\u043e\u0439 \u0441\u0442\u0440\u043e\u043a\u043e\u0439 \u0441 \u043e\u0434\u0438\u043d\u043e\u0447\u043d\u044b\u043c\u0438 \u043f\u0440\u043e\u0431\u0435\u043b\u0430\u043c\u0438-\u0440\u0430\u0437\u0434\u0435\u043b\u0438\u0442\u0435\u043b\u044f\u043c\u0438.\n\n**\u041f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u043c\u044b\u0435 \u0433\u0438\u043f\u043e\u0442\u0435\u0437\u044b (\u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0438 \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u043e\u0441\u0442\u0438):**\n- **H1 (\u043f\u043e\u0440\u044f\u0434\u043e\u043a):** \u0432\u044b\u0445\u043e\u0434\u043d\u0430\u044f \u0441\u0442\u0440\u043e\u043a\u0430 \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 \u0441\u043b\u043e\u0432\u0430 \u0432 \u043b\u0435\u043a\u0441\u0438\u043a\u043e\u0433\u0440\u0430\u0444\u0438\u0447\u0435\u0441\u043a\u0438 \u043d\u0435\u0443\u0431\u044b\u0432\u0430\u044e\u0449\u0435\u043c \u043f\u043e\u0440\u044f\u0434\u043a\u0435 \u043f\u043e \u0432\u044b\u0431\u0440\u0430\u043d\u043d\u043e\u043c\u0443 \u043f\u0440\u0430\u0432\u0438\u043b\u0443 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f (case-sensitive \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u043e Unicode-\u043a\u043e\u0434\u043e\u0432\u044b\u043c \u0442\u043e\u0447\u043a\u0430\u043c \u2014 \u0441\u043c. \u0420\u0430\u0437\u0434\u0435\u043b 6, \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435 A1).\n- **H2 (\u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c):** \u043a\u043e\u043b\u0438\u0447\u0435\u0441\u0442\u0432\u043e \u0441\u043b\u043e\u0432 \u043d\u0430 \u0432\u044b\u0445\u043e\u0434\u0435 \u0440\u0430\u0432\u043d\u043e \u043a\u043e\u043b\u0438\u0447\u0435\u0441\u0442\u0432\u0443 \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043e\u0432 \u0432\u0445\u043e\u0434\u043d\u043e\u0433\u043e \u0441\u043f\u0438\u0441\u043a\u0430 (\u0441 \u0443\u0447\u0451\u0442\u043e\u043c \u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0438 \u043f\u043e \u0434\u0443\u0431\u043b\u0438\u043a\u0430\u0442\u0430\u043c \u2014 \u043f\u043e\u0432\u0442\u043e\u0440\u0435\u043d\u0438\u044f \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u044e\u0442\u0441\u044f, A2; \u043f\u0443\u0441\u0442\u043e\u0439 \u0441\u043f\u0438\u0441\u043e\u043a \u2192 \u043f\u0443\u0441\u0442\u0430\u044f \u0441\u0442\u0440\u043e\u043a\u0430, A3).\n- **H3 (\u0444\u043e\u0440\u043c\u0430\u0442):** \u0432\u044b\u0432\u043e\u0434 \u2014 \u0440\u043e\u0432\u043d\u043e \u043e\u0434\u043d\u0430 \u0441\u0442\u0440\u043e\u043a\u0430; \u0440\u0430\u0437\u0434\u0435\u043b\u0438\u0442\u0435\u043b\u044c \u2014 \u043e\u0434\u0438\u043d\u043e\u0447\u043d\u044b\u0439 \u043f\u0440\u043e\u0431\u0435\u043b; \u043d\u0435\u0442 \u0432\u0435\u0434\u0443\u0449\u0438\u0445/\u0445\u0432\u043e\u0441\u0442\u043e\u0432\u044b\u0445 \u043f\u0440\u043e\u0431\u0435\u043b\u043e\u0432 \u0438 \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u043e\u0432 \u0441\u0442\u0440\u043e\u043a.\n- **H4 (\u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0441\u0442\u044c):** \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0439 \u0432\u0445\u043e\u0434 \u0432\u0441\u0435\u0433\u0434\u0430 \u0434\u0430\u0451\u0442 \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0439 \u0432\u044b\u0445\u043e\u0434 (\u043f\u0440\u0438 \u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u043e\u0439 \u0441\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u043a\u0435 \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0440\u0430\u0432\u043d\u044b\u0445 \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043e\u0432 \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u0435\u0442\u0441\u044f, A6).\n\n\u041a\u0430\u0436\u0434\u044b\u0439 \u0442\u0435\u0441\u0442 (\u0420\u0430\u0437\u0434\u0435\u043b 4) \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442 \u043f\u043e\u0434\u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u043e H1\u2013H4; \u0442\u0435\u0441\u0442 \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u043f\u0440\u043e\u0439\u0434\u0435\u043d\u043d\u044b\u043c \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u0438 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0438 \u0432\u0441\u0435\u0445 \u0440\u0435\u043b\u0435\u0432\u0430\u043d\u0442\u043d\u044b\u0445 \u0434\u043b\u044f \u043d\u0435\u0433\u043e \u0443\u0441\u043b\u043e\u0432\u0438\u0439.\n\n## 2. \u0412\u044b\u0431\u043e\u0440 \u0430\u043b\u0433\u043e\u0440\u0438\u0442\u043c\u0430 \u0438 \u043e\u0431\u043e\u0441\u043d\u043e\u0432\u0430\u043d\u0438\u0435 (\u0441 \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u044b\u043c \u044d\u0442\u0430\u043b\u043e\u043d\u043e\u043c)\n\n**\u041e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u0430\u043b\u0433\u043e\u0440\u0438\u0442\u043c (\u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u0430 \u043f\u043e\u0434 \u0442\u0435\u0441\u0442\u043e\u043c):** \u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u0430\u044f \u0441\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u043a\u0430 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435\u043c O(n log n) \u2014 \u0432 Python \u0432\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u044b\u0439 `sorted()` (TimSort) \u0441 \u043a\u043b\u044e\u0447\u043e\u043c \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f \u043f\u043e \u043e\u0431\u044a\u0435\u043a\u0442\u0443 \u0441\u043b\u043e\u0432\u0430. \u041e\u0431\u043e\u0441\u043d\u043e\u0432\u0430\u043d\u0438\u0435:\n- \u0433\u0430\u0440\u0430\u043d\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u0441\u043b\u043e\u0436\u043d\u043e\u0441\u0442\u044c O(n log n) \u0432 \u0445\u0443\u0434\u0448\u0435\u043c \u0441\u043b\u0443\u0447\u0430\u0435 \u0438 O(n) \u043d\u0430 \u043f\u043e\u0447\u0442\u0438-\u043e\u0442\u0441\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u0434\u0430\u043d\u043d\u044b\u0445;\n- \u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u043e\u0441\u0442\u044c (\u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u0435 \u043f\u043e\u0440\u044f\u0434\u043a\u0430 \u0440\u0430\u0432\u043d\u044b\u0445 \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043e\u0432) \u2014 \u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439, \u043f\u0440\u0435\u0434\u0441\u043a\u0430\u0437\u0443\u0435\u043c\u044b\u0439 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442;\n- \u0442\u043e\u043b\u044c\u043a\u043e \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u0430\u044f \u0431\u0438\u0431\u043b\u0438\u043e\u0442\u0435\u043a\u0430, \u0431\u0435\u0437 \u0432\u043d\u0435\u0448\u043d\u0438\u0445 \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0435\u0439.\n\n**\u041d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u044b\u0439 \u044d\u0442\u0430\u043b\u043e\u043d (\u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c):** Bucket/Counting-\u0441\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u043a\u0430 \u043f\u043e \u0431\u0430\u0439\u0442\u043e\u0432\u043e\u0439 (\u0438\u043b\u0438 \u043f\u043e\u0441\u0438\u043c\u0432\u043e\u043b\u044c\u043d\u043e\u0439) \u0440\u0430\u0441\u043a\u043b\u0430\u0434\u043a\u0435 \u0441\u043b\u043e\u0432, \u0440\u0430\u0431\u043e\u0442\u0430\u044e\u0449\u0430\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u043b\u044f \u0441\u043b\u043e\u0432 \u0441\u0442\u0440\u043e\u0433\u043e \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u043d\u043e\u0439 \u0434\u043b\u0438\u043d\u044b, \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u044e\u0449\u0430\u044f \u043f\u0440\u0438\u043d\u0446\u0438\u043f\u0438\u0430\u043b\u044c\u043d\u043e \u0434\u0440\u0443\u0433\u0443\u044e \u043c\u0435\u0442\u043e\u0434\u0438\u043a\u0443 (\u043d\u0435 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435). \u041e\u043d\u0430 \u0440\u0435\u0430\u043b\u0438\u0437\u0443\u0435\u0442 \u0442\u043e\u0442 \u0436\u0435 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u043f\u043e\u0440\u044f\u0434\u043a\u0430 (\u043a\u043e\u0434\u043e\u0432\u044b\u0435 \u0442\u043e\u0447\u043a\u0438) \u0438\u043d\u044b\u043c \u0441\u043f\u043e\u0441\u043e\u0431\u043e\u043c, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u0441\u043b\u0443\u0436\u0438\u0442 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c\u043d\u043e\u0439 \u0441\u0432\u0435\u0440\u043a\u043e\u0439: \u0435\u0441\u043b\u0438 \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u0430\u043b\u0433\u043e\u0440\u0438\u0442\u043c \u0434\u0430\u0451\u0442 \u0442\u043e\u0442 \u0436\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442, \u0447\u0442\u043e \u044d\u0442\u0430\u043b\u043e\u043d \u043d\u0430 \u0432\u0441\u0435\u0445 \u0434\u043e\u043f\u0443\u0441\u0442\u0438\u043c\u044b\u0445 \u0442\u0435\u0441\u0442\u043e\u0432\u044b\u0445 \u043d\u0430\u0431\u043e\u0440\u0430\u0445, \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u043e\u0441\u0442\u044c \u043f\u043e\u0440\u044f\u0434\u043a\u0430 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442\u0441\u044f \u0434\u0432\u0443\u043c\u044f \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u044b\u043c\u0438 \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f\u043c\u0438. \u0422\u0440\u0435\u0442\u0438\u0439 \u0442\u0440\u0438\u0432\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u044d\u0442\u0430\u043b\u043e\u043d \u2014 \u0441\u0432\u0435\u0440\u043a\u0430 \u0432\u044b\u0445\u043e\u0434\u043d\u043e\u0439 \u0441\u0442\u0440\u043e\u043a\u0438 \u0441 \u043a\u0430\u043d\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u043c \u043e\u0436\u0438\u0434\u0430\u0435\u043c\u044b\u043c \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435\u043c, \u0437\u0430\u043f\u0438\u0441\u0430\u043d\u043d\u044b\u043c \u0432\u0440\u0443\u0447\u043d\u0443\u044e \u0434\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0433\u043e \u0442\u0435\u0441\u0442-\u043a\u0435\u0439\u0441\u0430.\n\n\u042d\u0442\u0438 \u0442\u0440\u0438 \u0443\u0440\u043e\u0432\u043d\u044f (\u0432\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u044b\u0439 `sorted`, bucket-\u044d\u0442\u0430\u043b\u043e\u043d, \u0440\u0443\u0447\u043d\u043e\u0439 \u043a\u0430\u043d\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u044d\u0442\u0430\u043b\u043e\u043d) \u043e\u0431\u0440\u0430\u0437\u0443\u044e\u0442 \u043f\u0435\u0440\u0435\u043a\u0440\u0451\u0441\u0442\u043d\u0443\u044e \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0443, \u0438\u0441\u043a\u043b\u044e\u0447\u0430\u044e\u0449\u0443\u044e \u0441\u0438\u0441\u0442\u0435\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0443\u044e \u043e\u0448\u0438\u0431\u043a\u0443 \u043e\u0434\u043d\u043e\u0433\u043e \u043c\u0435\u0442\u043e\u0434\u0430.\n\n## 3. \u041f\u043b\u0430\u043d \u0442\u0435\u0441\u0442\u043e\u0432\u044b\u0445 \u0441\u043b\u0443\u0447\u0430\u0435\u0432\n\n| # | \u041a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u044f | \u0412\u0445\u043e\u0434 (\u043f\u0440\u0438\u043c\u0435\u0440) | \u041e\u0436\u0438\u0434\u0430\u0435\u043c\u043e\u0435 \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0438\u0435/\u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u043c\u043e\u0435 |\n|---|-----------|---------------|----------------------------------|\n| T1 | \u041e\u0431\u044b\u0447\u043d\u044b\u0435 ASCII-\u0441\u043b\u043e\u0432\u0430 | `banana apple cherry` | `apple banana cherry` (H1, H3) |\n| T2 | \u041f\u0443\u0441\u0442\u043e\u0439 \u0441\u043f\u0438\u0441\u043e\u043a | `` (\u043f\u0443\u0441\u0442\u0430\u044f \u0441\u0442\u0440\u043e\u043a\u0430) | \u043f\u0443\u0441\u0442\u0430\u044f \u0441\u0442\u0440\u043e\u043a\u0430 \u0431\u0435\u0437 \u043f\u0440\u043e\u0431\u0435\u043b\u043e\u0432 (H2, H3) |\n| T3 | \u041e\u0434\u0438\u043d \u044d\u043b\u0435\u043c\u0435\u043d\u0442 | `solitary` | `solitary` \u0431\u0435\u0437 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0439 (H1\u2013H3) |\n| T4 | \u0414\u0443\u0431\u043b\u0438\u043a\u0430\u0442\u044b | `apple banana apple` | `apple apple banana` \u2014 \u043f\u043e\u0432\u0442\u043e\u0440\u044b \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u044e\u0442\u0441\u044f (H1, H2) |\n| T5 | \u0421\u043c\u0435\u0448\u0430\u043d\u043d\u044b\u0439 \u0440\u0435\u0433\u0438\u0441\u0442\u0440 | `Zebra apple Banana` | `Banana Zebra apple`: \u0437\u0430\u0433\u043b\u0430\u0432\u043d\u044b\u0435 \u0440\u0430\u043d\u044c\u0448\u0435 \u0441\u0442\u0440\u043e\u0447\u043d\u044b\u0445 (\u043a\u043e\u0434\u043e\u0432\u044b\u0435 \u0442\u043e\u0447\u043a\u0438 A\u2013Z < a\u2013z); \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0438\u0440\u0443\u0435\u0442 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435 A1 (H1) |\n| T6 | \u041f\u0440\u043e\u0431\u0435\u043b\u044b/\u043f\u0443\u043d\u043a\u0442\u0443\u0430\u0446\u0438\u044f \u0432\u043e\u043a\u0440\u0443\u0433 \u0441\u043b\u043e\u0432 | ` cat  dog `, `a-b c.d` | \u0422\u043e\u043a\u0435\u043d\u044b \u0432\u044b\u0434\u0435\u043b\u044f\u044e\u0442\u0441\u044f \u043f\u043e \u043e\u0434\u0438\u043d\u043e\u0447\u043d\u044b\u043c \u043f\u0440\u043e\u0431\u0435\u043b\u0430\u043c; \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u0441\u043b\u043e\u0432\u0430 \u0431\u0435\u0437 \u043b\u0438\u0448\u043d\u0438\u0445 \u043f\u0440\u043e\u0431\u0435\u043b\u043e\u0432; \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u044f\u044f \u043f\u0443\u043d\u043a\u0442\u0443\u0430\u0446\u0438\u044f `a-b`, `c.d` \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u0447\u0430\u0441\u0442\u044c\u044e \u0441\u043b\u043e\u0432\u0430 (A4) (H1\u2013H3) |\n| T7 | \u041d\u0435-ASCII | `\u0451\u043b\u043a\u0430 \u044f\u0431\u043b\u043e\u043a\u043e \u0410\u0438\u0441\u0442` (\u043a\u0438\u0440\u0438\u043b\u043b\u0438\u0446\u0430) | \u041f\u043e\u0440\u044f\u0434\u043e\u043a \u043f\u043e Unicode-\u043a\u043e\u0434\u043e\u0432\u044b\u043c \u0442\u043e\u0447\u043a\u0430\u043c (\u043a\u0438\u0440\u0438\u043b\u043b\u0438\u0446\u0430 \u0438\u0434\u0451\u0442 \u043f\u043e\u0441\u043b\u0435 \u043b\u0430\u0442\u0438\u043d\u0438\u0446\u044b \u0438 \u0432 \u0441\u0432\u043e\u0451\u043c \u0434\u0438\u0430\u043f\u0430\u0437\u043e\u043d\u0435); \u0430\u043a\u0446\u0435\u043d\u0442\u044b/\u0434\u0438\u0430\u043a\u0440\u0438\u0442\u0438\u043a\u0430 \u0441\u043e\u0440\u0442\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u043f\u043e \u043a\u043e\u0434\u043e\u0432\u044b\u043c \u0442\u043e\u0447\u043a\u0430\u043c \u0431\u0435\u0437 \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438 (A1) (H1) |\n| T8 | \u0414\u043b\u0438\u043d\u043d\u044b\u0439 \u0441\u043f\u0438\u0441\u043e\u043a | 100 000 \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u044b\u0445 \u0441\u043b\u043e\u0432 | \u041f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0441\u043b\u043e\u0436\u043d\u043e\u0441\u0442\u0438: \u0432\u0440\u0435\u043c\u044f ~ O(n log n), \u043f\u0438\u043a\u043e\u0432\u0430\u044f \u043f\u0430\u043c\u044f\u0442\u044c ~ O(n) (\u0420\u0430\u0437\u0434\u0435\u043b 5) (H1\u2013H4) |\n| T9 | \u0421\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u043f\u0440\u0438 \u0440\u0430\u0432\u043d\u044b\u0445 | `apple Apple apple` | \u041e\u0442\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0440\u0430\u0432\u043d\u044b\u0445 \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043e\u0432 \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u0435\u0442\u0441\u044f \u2014 \u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u0430\u044f \u0441\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u043a\u0430 (A6) (H4) |\n\n\u0412\u0441\u0435 \u0442\u0435\u0441\u0442\u044b T1\u2013T7, T9 \u0438\u043c\u0435\u044e\u0442 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0432\u0445\u043e\u0434\u044b \u0438 \u043a\u0430\u043d\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043e\u0436\u0438\u0434\u0430\u0435\u043c\u044b\u0435 \u0432\u044b\u0445\u043e\u0434\u044b; T8 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442 \u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0443\u044e \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044e (\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0435 \u0437\u0435\u0440\u043d\u043e \u0413\u041f\u0421\u0427) \u0434\u043b\u044f \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u0438.\n\n## 4. \u041c\u0435\u0442\u0440\u0438\u043a\u0438\n\n- **\u041a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u043e\u0441\u0442\u044c \u043f\u043e\u0440\u044f\u0434\u043a\u0430:** \u0431\u0443\u043b\u0435\u0432 \u0444\u043b\u0430\u0433 \u0434\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0442\u0435\u0441\u0442\u0430 = (\u0432\u044b\u0445\u043e\u0434 === \u043a\u0430\u043d\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043e\u0436\u0438\u0434\u0430\u0435\u043c\u044b\u0439) \u0418 (\u0432\u044b\u0445\u043e\u0434 === \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0433\u043e \u044d\u0442\u0430\u043b\u043e\u043d\u0430) \u0434\u043b\u044f T1\u2013T7, T9; \u0434\u043b\u044f T8 \u2014 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0433\u043e \u0430\u043b\u0433\u043e\u0440\u0438\u0442\u043c\u0430 \u0441 \u044d\u0442\u0430\u043b\u043e\u043d\u043d\u044b\u043c `sorted`.\n- **\u0424\u043e\u0440\u043c\u0430\u0442 \u0432\u044b\u0432\u043e\u0434\u0430:** \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u00ab\u043e\u0434\u043d\u0430 \u0441\u0442\u0440\u043e\u043a\u0430, \u0431\u0435\u0437 `\\n`, \u043e\u0434\u0438\u043d\u043e\u0447\u043d\u044b\u0435 \u043f\u0440\u043e\u0431\u0435\u043b\u044b, \u0431\u0435\u0437 \u0432\u0435\u0434\u0443\u0449\u0438\u0445/\u0445\u0432\u043e\u0441\u0442\u043e\u0432\u044b\u0445 \u043f\u0440\u043e\u0431\u0435\u043b\u043e\u0432\u00bb (\u0440\u0430\u0437\u0431\u043e\u0440 \u0432\u044b\u0445\u043e\u0434\u0430 \u043f\u043e `split(' ')` \u0434\u043e\u043b\u0436\u0435\u043d \u0434\u0430\u0442\u044c \u0440\u043e\u0432\u043d\u043e \u0441\u043f\u0438\u0441\u043e\u043a \u043e\u0436\u0438\u0434\u0430\u0435\u043c\u044b\u0445 \u0441\u043b\u043e\u0432).\n- **\u0421\u043b\u043e\u0436\u043d\u043e\u0441\u0442\u044c \u043f\u043e \u0432\u0440\u0435\u043c\u0435\u043d\u0438:** \u0438\u0437\u043c\u0435\u0440\u0435\u043d\u043d\u043e\u0435 \u0432\u0440\u0435\u043c\u044f \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u044f \u043d\u0430 \u043d\u0430\u0431\u043e\u0440\u0430\u0445 \u0440\u0430\u0437\u043c\u0435\u0440\u0430\u043c\u0438 n = 10\u00b3, 10\u2074, 10\u2075 (T8); \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430, \u0447\u0442\u043e \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u0435 log-\u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u043a log-\u0440\u0430\u0437\u043c\u0435\u0440\u0443 ~ 1 (\u0441\u043e\u0432\u043c\u0435\u0441\u0442\u0438\u043c\u043e \u0441 O(n log n)).\n- **\u0421\u043b\u043e\u0436\u043d\u043e\u0441\u0442\u044c \u043f\u043e \u043f\u0430\u043c\u044f\u0442\u0438:** \u043f\u0438\u043a\u043e\u0432\u043e\u0435 \u043f\u043e\u0442\u0440\u0435\u0431\u043b\u0435\u043d\u0438\u0435 \u043f\u0430\u043c\u044f\u0442\u0438 (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u0447\u0435\u0440\u0435\u0437 `tracemalloc`) \u043d\u0430 n = 10\u2075, \u043e\u0436\u0438\u0434\u0430\u043d\u0438\u0435 ~ O(n).\n\n## 5. \u041f\u043b\u0430\u043d \u0430\u043d\u0430\u043b\u0438\u0437\u0430 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u043e\u0432\n\n1. \u0422\u0430\u0431\u043b\u0438\u0446\u0430 \u00ab\u0442\u0435\u0441\u0442 \u2192 \u0432\u0445\u043e\u0434 \u2192 \u043e\u0436\u0438\u0434\u0430\u043d\u0438\u0435 \u2192 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 (\u043e\u0436\u0438\u0434\u0430\u0435\u043c\u044b\u0439) \u2192 \u0441\u0442\u0430\u0442\u0443\u0441 \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0438\u044f H1\u2013H4\u00bb.\n2. \u0421\u0432\u043e\u0434\u043a\u0430: \u0434\u043e\u043b\u044f \u043f\u0440\u043e\u0439\u0434\u0435\u043d\u043d\u044b\u0445 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0435\u0432; \u043b\u044e\u0431\u044b\u0435 \u0433\u0438\u043f\u043e\u0442\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u0440\u0430\u0441\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u044f \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u044e\u0442\u0441\u044f \u043f\u043e \u043f\u0440\u0438\u0447\u0438\u043d\u0435 (\u0440\u0435\u0433\u0438\u0441\u0442\u0440 A1, \u0434\u0443\u0431\u043b\u0438\u043a\u0430\u0442\u044b A2, \u043f\u0443\u0441\u0442\u044b\u0435 \u0442\u043e\u043a\u0435\u043d\u044b A3, \u0432\u0432\u043e\u0434 A4, Unicode A1).\n3. \u041e\u0446\u0435\u043d\u043a\u0430 \u043c\u0430\u0441\u0448\u0442\u0430\u0431\u0438\u0440\u0443\u0435\u043c\u043e\u0441\u0442\u0438: \u043d\u0430\u043a\u043b\u043e\u043d log(time)/log(n) \u043f\u043e T8 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442 \u0438\u043b\u0438 \u043e\u043f\u0440\u043e\u0432\u0435\u0440\u0433\u0430\u0435\u0442 O(n log n); \u043f\u0438\u043a\u043e\u0432\u0430\u044f \u043f\u0430\u043c\u044f\u0442\u044c \u0441\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u0441 \u043e\u0436\u0438\u0434\u0430\u0435\u043c\u043e\u0439 O(n).\n4. \u0418\u0442\u043e\u0433\u043e\u0432\u044b\u0439 \u0432\u044b\u0432\u043e\u0434 \u043e \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0438\u0438 \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u043e\u0439 \u0432\u0441\u0435\u0445 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0435\u0432 H1\u2013H4 \u043d\u0430 \u0441\u043f\u0440\u043e\u0435\u043a\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u043c \u043d\u0430\u0431\u043e\u0440\u0435 \u0442\u0435\u0441\u0442\u043e\u0432. \u041d\u0438\u043a\u0430\u043a\u0438\u0445 \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u0432 \u043d\u0435 \u043e\u0431\u044a\u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u2014 \u0440\u0430\u0437\u0434\u0435\u043b \u043e\u043f\u0438\u0441\u044b\u0432\u0430\u0435\u0442 \u043f\u0440\u043e\u0446\u0435\u0434\u0443\u0440\u0443 \u0438 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0438 \u043f\u0440\u0438\u0451\u043c\u043a\u0438.\n\n## 6. \u041e\u0446\u0435\u043d\u043a\u0430 \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u043c\u043e\u0441\u0442\u0438\n\n- **Runtime:** \u0432\u0441\u0435 \u0442\u0435\u0441\u0442\u044b (\u0432\u043a\u043b\u044e\u0447\u0430\u044f T8, 100k \u0441\u043b\u043e\u0432) \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u044e\u0442\u0441\u044f \u0437\u0430 \u0434\u043e\u043b\u0438 \u0441\u0435\u043a\u0443\u043d\u0434\u044b \u043f\u0440\u0438 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u0438 \u0432\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u043e\u0433\u043e `sorted`; bucket-\u044d\u0442\u0430\u043b\u043e\u043d \u043f\u0440\u0438\u043c\u0435\u043d\u0438\u043c \u0442\u043e\u043b\u044c\u043a\u043e \u043a \u0441\u043b\u043e\u0432\u0430\u043c \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u043d\u043e\u0439 \u0434\u043b\u0438\u043d\u044b \u0438 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u043d\u0430 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u043d\u0430\u0431\u043e\u0440\u0430\u0445 T1\u2013T7, T9.\n- **\u041f\u0430\u043c\u044f\u0442\u044c:** \u043f\u0438\u043a\u043e\u0432\u0430\u044f \u043f\u0430\u043c\u044f\u0442\u044c O(n) \u0434\u043b\u044f \u0441\u043f\u0438\u0441\u043a\u0430 \u0441\u0442\u0440\u043e\u043a \u2014 \u043f\u0440\u0435\u043d\u0435\u0431\u0440\u0435\u0436\u0438\u043c\u043e \u043c\u0430\u043b\u0430 \u043f\u0440\u0438 n \u2264 10\u2075.\n- **\u0417\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0438:** \u0442\u043e\u043b\u044c\u043a\u043e \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u0430\u044f \u0431\u0438\u0431\u043b\u0438\u043e\u0442\u0435\u043a\u0430 Python 3.14 (\u0434\u043e\u0441\u0442\u0443\u043f\u043d\u0430 \u0432 \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u0438); \u0441\u0435\u0442\u044c \u043d\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044f (\u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0430); \u043f\u0440\u043e\u0435\u043a\u0442 \u043d\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u043f\u0440\u0435\u0434\u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043d\u044b\u0445 \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0435\u0439.\n- \u0415\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0435 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0435 \u2014 \u044d\u0442\u043e design-only \u0437\u0430\u0434\u0430\u0447\u0430: \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442 \u043d\u0435 \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u0435\u0442\u0441\u044f, \u043e\u0446\u0435\u043d\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0433\u043e\u0442\u043e\u0432\u043d\u043e\u0441\u0442\u044c \u0438 \u043e\u0431\u043e\u0441\u043d\u043e\u0432\u0430\u043d\u043d\u043e\u0441\u0442\u044c \u0434\u0438\u0437\u0430\u0439\u043d\u0430.\n\n## 7. \u0414\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f \u0438 \u043d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0441\u0442\u0438\n\n**\u0417\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f (\u043f\u0440\u0438\u043d\u0438\u043c\u0430\u044e\u0442\u0441\u044f \u043a\u0430\u043a \u0440\u0430\u0437\u0443\u043c\u043d\u044b\u0439 \u0432\u044b\u0431\u043e\u0440, \u041d\u0415 \u043a\u0430\u043a \u0444\u0430\u043a\u0442\u044b \u0438\u0437 \u0437\u0430\u0434\u0430\u043d\u0438\u044f):**\n- A1. **\u041f\u0440\u0430\u0432\u0438\u043b\u043e \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f (\u0440\u0435\u0433\u0438\u0441\u0442\u0440):** \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d \u041e\u0414\u0418\u041d \u0431\u0430\u0437\u043e\u0432\u044b\u0439 \u0440\u0435\u0436\u0438\u043c \u2014 case-sensitive \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u043e Unicode-\u043a\u043e\u0434\u043e\u0432\u044b\u043c \u0442\u043e\u0447\u043a\u0430\u043c (A\u2013Z < a\u2013z; \u043a\u0438\u0440\u0438\u043b\u043b\u0438\u0446\u0430 \u0432 \u0441\u0432\u043e\u0451\u043c \u0434\u0438\u0430\u043f\u0430\u0437\u043e\u043d\u0435 \u043f\u043e\u0441\u043b\u0435 \u043b\u0430\u0442\u0438\u043d\u0438\u0446\u044b). \u0421\u043c\u0435\u0448\u0430\u043d\u043d\u044b\u0439 \u0440\u0435\u0433\u0438\u0441\u0442\u0440 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442\u0441\u044f \u0442\u0435\u0441\u0442\u043e\u043c T5, \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0438\u0440\u0443\u044e\u0449\u0438\u043c \u044d\u0442\u043e \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0438\u0435. \u042d\u0442\u043e \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435, \u0430 \u043d\u0435 \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u0435 \u0437\u0430\u0434\u0430\u043d\u0438\u044f.\n- A2. **\u0414\u0443\u0431\u043b\u0438\u043a\u0430\u0442\u044b:** \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u044e\u0442\u0441\u044f \u2014 \u043a\u0430\u0436\u0434\u043e\u0435 \u0432\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u0435 \u0432\u044b\u0432\u043e\u0434\u0438\u0442\u0441\u044f.\n- A3. **\u041f\u0443\u0441\u0442\u043e\u0439 \u0441\u043f\u0438\u0441\u043e\u043a:** \u043f\u0443\u0441\u0442\u0430\u044f \u0441\u0442\u0440\u043e\u043a\u0430 \u0432\u044b\u0432\u043e\u0434\u0438\u0442\u0441\u044f \u043a\u0430\u043a \u043f\u0443\u0441\u0442\u043e\u0439 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442; \u043f\u0443\u0441\u0442\u044b\u0435 \u0442\u043e\u043a\u0435\u043d\u044b \u0432\u043d\u0443\u0442\u0440\u0438 \u0441\u043f\u0438\u0441\u043a\u0430 \u043d\u0435\u0434\u043e\u043f\u0443\u0441\u0442\u0438\u043c\u044b \u043f\u0440\u0438 \u0432\u044b\u0431\u0440\u0430\u043d\u043d\u043e\u043c \u0444\u043e\u0440\u043c\u0430\u0442\u0435 \u0432\u0432\u043e\u0434\u0430 (\u0441\u043c. A4), \u043f\u0440\u0438 \u0434\u0440\u0443\u0433\u043e\u043c \u0444\u043e\u0440\u043c\u0430\u0442\u0435 \u2014 \u043e\u0442\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u044e\u0442\u0441\u044f \u0438\u043b\u0438 \u0442\u0440\u0430\u043a\u0442\u0443\u044e\u0442\u0441\u044f \u043a\u0430\u043a \u0441\u043b\u043e\u0432\u0430 \u043f\u043e \u044f\u0432\u043d\u043e\u0439 \u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0435.\n- A4. **\u0424\u043e\u0440\u043c\u0430\u0442 \u0432\u0432\u043e\u0434\u0430:** \u043e\u0434\u043d\u0430 \u0441\u0442\u0440\u043e\u043a\u0430 \u0441\u043b\u043e\u0432, \u0440\u0430\u0437\u0434\u0435\u043b\u0451\u043d\u043d\u044b\u0445 \u043f\u0440\u043e\u0431\u0435\u043b\u0430\u043c\u0438 (\u0440\u0430\u0437\u0443\u043c\u043d\u044b\u0439 \u0432\u0430\u0440\u0438\u0430\u043d\u0442). \u042d\u0442\u043e \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435, \u043d\u0435 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0451\u043d\u043d\u043e\u0435 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u043e\u043c.\n- A5. **\u041f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c:** \u043e\u0440\u0438\u0435\u043d\u0442\u0438\u0440 O(n log n)/O(n) \u0438 \u00ab\u043c\u0433\u043d\u043e\u0432\u0435\u043d\u043d\u043e\u0435\u00bb \u0432\u0440\u0435\u043c\u044f \u043d\u0430 100k \u0441\u043b\u043e\u0432; \u0436\u0451\u0441\u0442\u043a\u0438\u0445 \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u0439 \u043d\u0435\u0442.\n- A6. **\u0421\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u043e\u0441\u0442\u044c:** \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u0435\u0442\u0441\u044f \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0440\u0430\u0432\u043d\u044b\u0445 \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043e\u0432 (TimSort).\n\n**\u0418\u0437\u043c\u0435\u043d\u044f\u0435\u043c\u044b\u0435 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f (\u0434\u0438\u0437\u0430\u0439\u043d \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u044b\u043c \u043f\u0440\u0438 \u0441\u043c\u0435\u043d\u0435):**\n- \u0421\u043c\u0435\u043d\u0430 \u043f\u0440\u0430\u0432\u0438\u043b\u0430 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f \u043d\u0430 case-insensitive (A1): \u0437\u0430\u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0444\u0443\u043d\u043a\u0446\u0438\u044f \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f/\u043a\u043b\u044e\u0447; \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430 \u0442\u0435\u0441\u0442\u043e\u0432 (\u043f\u043e\u0440\u044f\u0434\u043e\u043a \u043a\u0430\u043a \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 H1) \u0438 \u043c\u0435\u0442\u0440\u0438\u043a\u0438 \u043d\u0435 \u043c\u0435\u043d\u044f\u044e\u0442\u0441\u044f; \u0434\u043b\u044f T5 \u043f\u0435\u0440\u0435\u0441\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u043e\u0436\u0438\u0434\u0430\u0435\u043c\u044b\u0439 \u0432\u044b\u0445\u043e\u0434.\n- \u0421\u043c\u0435\u043d\u0430 \u0444\u043e\u0440\u043c\u0430\u0442\u0430 \u0432\u0432\u043e\u0434\u0430 (A4, \u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440 \u0437\u0430\u043f\u044f\u0442\u0430\u044f \u0438\u043b\u0438 \u043f\u043e\u0441\u0442\u0440\u043e\u0447\u043d\u043e): \u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0430\u0440\u0441\u0435\u0440 \u0442\u043e\u043a\u0435\u043d\u043e\u0432; \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0438 H1\u2013H4 \u0438 \u0442\u0435\u0441\u0442\u043e\u0432\u044b\u0435 \u043d\u0430\u0431\u043e\u0440\u044b (\u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f \u0432\u0445\u043e\u0434\u043e\u0432) \u0430\u0434\u0430\u043f\u0442\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u044d\u043a\u0432\u0438\u0432\u0430\u043b\u0435\u043d\u0442\u043d\u043e, \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430 \u0434\u0438\u0437\u0430\u0439\u043d\u0430 \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f \u0442\u043e\u0439 \u0436\u0435.\n\n**\u041d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0441\u0442\u0438 (\u043d\u0435 \u0437\u0430\u043a\u0440\u044b\u0442\u044b \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u043e\u043c, \u043e\u0441\u0442\u0430\u044e\u0442\u0441\u044f \u043d\u0430 \u0443\u0441\u043c\u043e\u0442\u0440\u0435\u043d\u0438\u0435):**\n- U1. \u0422\u043e\u0447\u043d\u044b\u0439 \u0444\u043e\u0440\u043c\u0430\u0442 \u0432\u0432\u043e\u0434\u0430/\u0432\u044b\u0432\u043e\u0434\u0430 \u0438 \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u0435 \u043a \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0443 \u043d\u0435 \u0443\u043a\u0430\u0437\u0430\u043d\u044b \u0432 task.json; \u043c\u043e\u0433\u0443\u0442 \u0431\u044b\u0442\u044c \u0443\u0442\u043e\u0447\u043d\u0435\u043d\u044b \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u0438 \u043f\u043e\u044f\u0432\u043b\u0435\u043d\u0438\u0438 \u0434\u043e\u043f. \u0441\u043f\u0435\u0446\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0438.\n- U2. \u0421\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u0441\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u043a\u0438 \u0438 \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u0435 \u043f\u043e\u0432\u0442\u043e\u0440\u043e\u0432 \u043d\u0435 \u043e\u0433\u043e\u0432\u043e\u0440\u0435\u043d\u044b \u2014 \u043f\u0440\u0438\u043d\u044f\u0442\u044b \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f A2, A6.\n- U3. \u0416\u0451\u0441\u0442\u043a\u0438\u0435 \u043b\u0438\u043c\u0438\u0442\u044b \u0432\u0440\u0435\u043c\u0435\u043d\u0438/\u043f\u0430\u043c\u044f\u0442\u0438 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0442 \u2014 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d \u043e\u0440\u0438\u0435\u043d\u0442\u0438\u0440 A5.\n- U4. \u041d\u0435-ASCII-\u043d\u0430\u0431\u043e\u0440\u044b (\u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u044b\u0435 \u0441\u043b\u043e\u0432\u0430) \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0442 \u0432 \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0438 \u2014 \u0432\u0445\u043e\u0434\u044b \u0433\u0435\u043d\u0435\u0440\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0432 \u0434\u0438\u0437\u0430\u0439\u043d\u0435 (T7).\n\n## 8. \u041f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u0435 sources (\u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0439)\n\n- `/workspace` \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 \u0442\u043e\u043b\u044c\u043a\u043e `task.json`; `documents.track.md` \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442 \u00abDesign-only task; repositories and compute are not required\u00bb. \u041d\u0438 \u043a\u043e\u0434\u0430, \u043d\u0438 \u0442\u0435\u0441\u0442\u043e\u0432\u044b\u0445 \u0434\u0430\u043d\u043d\u044b\u0445, \u043d\u0438 \u0441\u043f\u0435\u0446\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0438 \u0432\u0432\u043e\u0434\u0430/\u0432\u044b\u0432\u043e\u0434\u0430 \u043d\u0435\u0442. \u041e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u0435: Python 3.14.4, \u0441\u0435\u0442\u044c \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0430. \u0412\u0441\u0435 \u0432\u044b\u0432\u043e\u0434\u044b \u043e \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0438\u0438 \u2014 \u043f\u0440\u043e\u0435\u043a\u0442\u043d\u044b\u0435 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f, \u043d\u0435 \u0437\u0430\u044f\u0432\u043b\u0435\u043d\u043d\u044b\u0435 \u043a\u0430\u043a \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u043d\u044b\u0435 \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u044b.", "stage": "result", "summary": "Deliver complete experiment design with assumptions and expected outcomes only.", "evidence": "\u0418\u043d\u0441\u043f\u0435\u043a\u0446\u0438\u044f /workspace: \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0444\u0430\u0439\u043b task.json (query `find /workspace -maxdepth 3` \u0432\u0435\u0440\u043d\u0443\u043b \u0442\u043e\u043b\u044c\u043a\u043e task.json); task.json \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 question \u00abBuild a word sorting program that alphabetically sorts a list of words and returns them as a single line of text with spaces between words.\u00bb \u0438 documents.track.md = \u00abDesign-only task; repositories and compute are not required.\u00bb \u041e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u0435: python3 = 3.14.4 (\u043f\u0440\u043e\u0432\u0435\u0440\u0435\u043d\u043e `python3 --version`), \u0441\u0435\u0442\u044c \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0430, \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0435\u0439 \u043d\u0435\u0442. \u042d\u0442\u043e \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442 design-only \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442 \u0438 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0435 \u0432\u0445\u043e\u0434\u043e\u0432/\u0441\u043f\u0435\u0446\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0439, \u043d\u0430 \u0447\u0442\u043e \u043e\u043f\u0438\u0440\u0430\u044e\u0442\u0441\u044f \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f A1\u2013A6 \u0438 \u043d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0441\u0442\u0438 U1\u2013U4. \u042d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442 \u043d\u0435 \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u043b\u0441\u044f; \u0440\u0430\u0437\u0434\u0435\u043b\u044b \u0441 \u00ab\u043e\u0436\u0438\u0434\u0430\u0435\u043c\u044b\u043c\u0438\u00bb \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0430\u043c\u0438 \u043e\u043f\u0438\u0441\u044b\u0432\u0430\u044e\u0442 \u043f\u0440\u043e\u0433\u043d\u043e\u0437\u044b \u0438 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0438 \u043f\u0440\u0438\u0451\u043c\u043a\u0438, \u0430 \u043d\u0435 \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043f\u0440\u043e\u0433\u043e\u043d\u044b.", "assumptions